import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.File;

/**
 * Draws curseforge/icon.png from scratch: a white border, a red flesh texture made from noise with
 * eyes scattered over it, and "EYES / PATCH" in hand-made pixel letters. No font, no eYes asset,
 * nothing generated by AI.
 * Run from the repo root: java curseforge/MakeIcon.java curseforge/icon.png
 */
public class MakeIcon {
    static final int GRID = 52;
    static final int CELL = 10;
    static final int BORDER = 2;
    static final long SEED = 1_016_2026L;

    static final int WHITE = 0xFFFFFF;
    static final int OUTLINE = 0x140306;
    static final int SHADOW = 0x2A060C;
    /** Flesh tones, darkest to lightest, then the eyes: lid, white, iris, pupil. */
    static final int[] TISSUE = {0x3E0A12, 0x5E101B, 0x7E1823, 0x9C2530, 0xB8393F, 0xD25A57};
    static final int LID = 0x2A050B;
    static final int SCLERA = 0xF2E6E0;
    static final int IRIS = 0xE36A12;
    static final int IRIS_RING = 0x8C2A08;
    static final int PUPIL = 0x0B0204;
    static final int EYES = 18;

    static final String[] P = {
            "######.",
            "#######",
            "##...##",
            "##...##",
            "##...##",
            "#######",
            "######.",
            "##.....",
            "##.....",
            "##.....",
            "##....."};
    static final String[] E = {
            "#######",
            "#######",
            "##.....",
            "##.....",
            "##.....",
            "######.",
            "######.",
            "##.....",
            "##.....",
            "#######",
            "#######"};
    static final String[] Y = {
            "##...##",
            "##...##",
            "##...##",
            ".##.##.",
            ".#####.",
            "..###..",
            "..###..",
            "..###..",
            "..###..",
            "..###..",
            "..###.."};
    static final String[] S = {
            ".######",
            "#######",
            "##.....",
            "##.....",
            "######.",
            ".######",
            ".....##",
            ".....##",
            ".....##",
            "#######",
            "######."};
    static final String[] A = {
            ".#####.",
            "#######",
            "##...##",
            "##...##",
            "##...##",
            "#######",
            "#######",
            "##...##",
            "##...##",
            "##...##",
            "##...##"};
    static final String[] T = {
            "######",
            "######",
            "..##..",
            "..##..",
            "..##..",
            "..##..",
            "..##..",
            "..##..",
            "..##..",
            "..##..",
            "..##.."};
    static final String[] C = {
            ".######",
            "#######",
            "##.....",
            "##.....",
            "##.....",
            "##.....",
            "##.....",
            "##.....",
            "##.....",
            "#######",
            ".######"};
    static final String[] H = {
            "##...##",
            "##...##",
            "##...##",
            "##...##",
            "#######",
            "#######",
            "##...##",
            "##...##",
            "##...##",
            "##...##",
            "##...##"};

    public static void main(String[] args) throws Exception {
        int[][] color = new int[GRID][GRID];
        for (int y = 0; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                color[y][x] = tissue(x, y);
            }
        }
        drawEyes(color);

        boolean[][] text = new boolean[GRID][GRID];
        int letterGap = 2;
        int lineGap = 4;
        String[][] top = {E, Y, E, S};
        String[][] bottom = {P, A, T, C, H};
        int height = 11 + lineGap + 11;
        int y0 = (GRID - height) / 2;
        stamp(text, top, letterGap, y0);
        stamp(text, bottom, letterGap, y0 + 11 + lineGap);

        boolean[][] outline = grow(text);
        for (int y = 0; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                if (x >= 1 && y >= 1 && outline[y - 1][x - 1] && !outline[y][x]) {
                    color[y][x] = SHADOW;
                }
            }
        }
        for (int y = 0; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                if (text[y][x]) {
                    color[y][x] = WHITE;
                } else if (outline[y][x]) {
                    color[y][x] = OUTLINE;
                }
            }
        }

        for (int y = 0; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                if (x < BORDER || y < BORDER || x >= GRID - BORDER || y >= GRID - BORDER) {
                    color[y][x] = WHITE;
                }
            }
        }

        BufferedImage image = new BufferedImage(GRID * CELL, GRID * CELL, BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < GRID * CELL; y++) {
            for (int x = 0; x < GRID * CELL; x++) {
                image.setRGB(x, y, color[y / CELL][x / CELL]);
            }
        }
        ImageIO.write(image, "png", new File(args[0]));
    }

    /** Picks a flesh tone from layered noise, with a dark edge. */
    static int tissue(int x, int y) {
        double tone = fbm(x / 10.0, y / 10.0, 0);
        double fromCenter = Math.max(Math.abs(x - (GRID - 1) / 2.0), Math.abs(y - (GRID - 1) / 2.0)) / ((GRID - 1) / 2.0);
        double grain = (hash(x, y, 2) - 0.5) * 0.12;
        double level = tone * 1.25 - 0.1 + grain - Math.max(0.0, fromCenter - 0.6) * 0.9;
        int index = (int) Math.floor(level * 5.0);
        index = Math.max(0, Math.min(4, index));
        if (index == 4 && hash(x, y, 3) > 0.85) {
            index = 5;
        }
        return TISSUE[index];
    }

    /** Almond eyes with a dark lid, an orange iris and a slit pupil, scattered over the flesh. */
    static void drawEyes(int[][] color) {
        for (int i = 0; i < EYES; i++) {
            double cx = BORDER + 2 + hash(i, 0, 5) * (GRID - 2 * BORDER - 4);
            double cy = BORDER + 2 + hash(i, 1, 5) * (GRID - 2 * BORDER - 4);
            double size = 2.0 + hash(i, 2, 5) * 1.8;
            for (int y = 0; y < GRID; y++) {
                for (int x = 0; x < GRID; x++) {
                    double dx = (x - cx) / (size * 1.6);
                    double dy = (y - cy) / size;
                    double shape = dx * dx + dy * dy;
                    double eye = Math.hypot(x - cx, y - cy);
                    if (shape <= 1.0) {
                        if (Math.abs(x - cx) <= 0.7 && Math.abs(y - cy) <= size * 0.75) {
                            color[y][x] = PUPIL;
                        } else if (eye <= size * 0.7) {
                            color[y][x] = IRIS;
                        } else if (eye <= size * 1.0) {
                            color[y][x] = IRIS_RING;
                        } else {
                            color[y][x] = SCLERA;
                        }
                    } else if (shape <= 1.6) {
                        color[y][x] = LID;
                    }
                }
            }
        }
    }

    static void stamp(boolean[][] mask, String[][] letters, int gap, int y0) {
        int width = 0;
        for (String[] letter : letters) {
            width += letter[0].length();
        }
        width += gap * (letters.length - 1);
        int x = (GRID - width) / 2;
        for (String[] letter : letters) {
            for (int row = 0; row < letter.length; row++) {
                for (int col = 0; col < letter[row].length(); col++) {
                    if (letter[row].charAt(col) == '#') {
                        mask[y0 + row][x + col] = true;
                    }
                }
            }
            x += letter[0].length() + gap;
        }
    }

    /** The mask plus every cell next to it, diagonals included. */
    static boolean[][] grow(boolean[][] mask) {
        boolean[][] out = new boolean[GRID][GRID];
        for (int y = 0; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                for (int dy = -1; dy <= 1 && !out[y][x]; dy++) {
                    for (int dx = -1; dx <= 1; dx++) {
                        int nx = x + dx;
                        int ny = y + dy;
                        if (nx >= 0 && ny >= 0 && nx < GRID && ny < GRID && mask[ny][nx]) {
                            out[y][x] = true;
                            break;
                        }
                    }
                }
            }
        }
        return out;
    }

    static double fbm(double x, double y, int layer) {
        double sum = 0;
        double amplitude = 0.5;
        double total = 0;
        for (int octave = 0; octave < 4; octave++) {
            sum += amplitude * noise(x, y, layer * 16 + octave);
            total += amplitude;
            x *= 2.0;
            y *= 2.0;
            amplitude *= 0.5;
        }
        return sum / total;
    }

    /** Smoothly interpolated value noise in 0..1. */
    static double noise(double x, double y, int layer) {
        int x0 = (int) Math.floor(x);
        int y0 = (int) Math.floor(y);
        double fx = x - x0;
        double fy = y - y0;
        double sx = fx * fx * (3 - 2 * fx);
        double sy = fy * fy * (3 - 2 * fy);
        double a = hash(x0, y0, layer);
        double b = hash(x0 + 1, y0, layer);
        double c = hash(x0, y0 + 1, layer);
        double d = hash(x0 + 1, y0 + 1, layer);
        return (a + (b - a) * sx) * (1 - sy) + (c + (d - c) * sx) * sy;
    }

    static double hash(int x, int y, int layer) {
        long h = SEED ^ (x * 0x9E3779B97F4A7C15L) ^ (y * 0xC2B2AE3D27D4EB4FL) ^ (layer * 0x165667B19E3779F9L);
        h ^= h >>> 33;
        h *= 0xFF51AFD7ED558CCDL;
        h ^= h >>> 33;
        h *= 0xC4CEB9FE1A85EC53L;
        h ^= h >>> 33;
        return (h >>> 11) / (double) (1L << 53);
    }
}
